"""Parking-only integration. Dedicated local kgp_parking_02_test database only."""
import argparse,json,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];FOLDER=ROOT/'docs/catalogue/kgp-parking-02'
p=argparse.ArgumentParser();p.add_argument('--docker');a=p.parse_args()
cmd=(['docker','exec','-i',a.docker] if a.docker else [])+['psql','-X','-U','postgres','-d','kgp_parking_02_test','-qAt','-v','ON_ERROR_STOP=1']
def sql(s,error=None):
 r=subprocess.run(cmd,input=s,text=True,capture_output=True)
 if error:assert r.returncode and error in r.stderr,r.stderr
 else:assert r.returncode==0,r.stderr
 return r.stdout.strip()
def lit(v):return '$seed$'+json.dumps(v,ensure_ascii=True)+'$seed$::jsonb'
rows=json.loads((FOLDER/'records.json').read_text());original=json.loads((ROOT/'docs/catalogue/kgp-practical-01/records.json').read_text());by={r['peak_slug']:r for r in rows}
apply=(FOLDER/'apply.sql').read_text(encoding='ascii');rollback=(FOLDER/'rollback.sql').read_text(encoding='ascii');verify=(FOLDER/'verify.sql').read_text(encoding='ascii')
assert all(s.isascii() for s in [apply,rollback,verify])
def reset():
 sql('do $$begin create role anon;exception when duplicate_object then null;end$$;do $$begin create role authenticated;exception when duplicate_object then null;end$$;drop schema if exists peakguide_private cascade;drop schema public cascade;create schema public;')
 fixture=(ROOT/'supabase/tests/kgp_practical_fixture.sql').read_text()
 fixture=fixture.replace('id bigserial primary key','id bigint generated by default as identity primary key').replace('latitude numeric,longitude numeric','latitude numeric(9,6),longitude numeric(9,6)').replace('active boolean default true,created_at timestamptz default now()','active boolean not null default true,created_at timestamptz not null default now()').replace('is_primary boolean default false','is_primary boolean not null default false').replace('lang varchar(8)','lang varchar')
 sql(fixture)
 seed=[]
 for index,r in enumerate(original):
  t=r['expected_trail'];seed.append(f"insert into peaks(id,slug)values({t['peak_id']},'{r['peak_slug']}');insert into trails select (jsonb_populate_record(null::trails,{lit(dict(t,active=True,distance_km=5,route_geometry={'type':'LineString','coordinates':[[20,50],[20.1,50.1]]},gpx_url='https://example.org/retain.gpx'))})).*;")
  if r['peak_slug'] in by:acc=by[r['peak_slug']]['before']['access'][0]
  else:acc={'row':dict(r['access'],id=2000+index,trail_id=t['id'],created_at='2026-11-22T00:00:00Z'),'i18n':[dict(x,lang=l,access_id=2000+index) for l,x in r['i18n'].items()]}
  seed.append(f"insert into trail_access select (jsonb_populate_record(null::trail_access,{lit(acc['row'])})).*;")
  for txt in acc['i18n']:seed.append(f"insert into trail_access_i18n select (jsonb_populate_record(null::trail_access_i18n,{lit(txt)})).*;")
  for park in r['parking']:
   pid=3000+index;seed.append(f"insert into trail_parking select (jsonb_populate_record(null::trail_parking,{lit(dict(park['row'],id=pid,trail_id=t['id'],created_at='2026-11-22T00:00:00Z'))})).*;")
   for l,txt in park['i18n'].items():seed.append(f"insert into trail_parking_i18n select (jsonb_populate_record(null::trail_parking_i18n,{lit(dict(txt,lang=l,parking_id=pid))})).*;")
 sql('\n'.join(seed))
 sql("select setval(pg_get_serial_sequence('trail_parking','id'),4000);insert into peakguide_private.catalogue_batch_receipts(batch_key,snapshot)values('kgp-practical-01','{\"preserve_original_receipt\":true}'),('foreign-gpx-01','{\"preserve_foreign_receipt\":true}');create table user_trail_links(trail_id bigint references trails,label text);insert into user_trail_links values(36,'Preserve user relation');")
def snap():
 return {t:json.loads(sql(f"select coalesce(jsonb_agg(v order by v::text),'[]') from(select to_jsonb(t) v from {t} t) q;")) for t in ['peaks','trails','trail_access','trail_access_i18n','trail_parking','trail_parking_i18n','peakguide_private.catalogue_batch_receipts','user_trail_links']}
reset();before=snap();sql(rollback);assert snap()==before
sql(apply);after=snap()
for table in ['peaks','trails','trail_access','trail_access_i18n','user_trail_links']:assert before[table]==after[table],table
for table in ['trail_parking','trail_parking_i18n','peakguide_private.catalogue_batch_receipts']:
 assert all(v in after[table] for v in before[table]),table
assert len(after['trail_parking'])==25 and len(after['trail_parking_i18n'])==100
assert len(after['trail_access'])==28 and len(after['trail_access_i18n'])==112
checks=[json.loads(l) for l in sql('select row_to_json(q) from('+verify.strip().removesuffix(';')+') q;').splitlines()]
assert len(checks)==16 and all(r['parking_cards']==1 and r['parking_translations']==4 and r['access_cards']==1 and r['access_translations']==4 and r['package_applied'] and r['route_identity_matches'] for r in checks)
all_verify=(FOLDER/'verify-all.sql').read_text(encoding='ascii')
all_checks=[json.loads(l) for l in sql('select row_to_json(q) from('+all_verify.strip().removesuffix(';')+') q;').splitlines()]
assert len(all_checks)==28 and sum(r['parking_cards'] for r in all_checks)==25
assert all(r['parking_cards']==r['expected_parking_cards'] and r['parking_translations']==4*r['parking_cards'] and r['access_cards']==1 and r['access_translations']==4 and r['route_identity_matches'] for r in all_checks)
for role in ['anon','authenticated']:
 assert sql(f'set role {role};select count(*) from trail_parking;')=='25'
 sql(f'set role {role};'+apply,'Owner execution required');assert snap()==after
sql("set timezone='Asia/Shanghai';"+apply);assert snap()==after
sql("set timezone='America/New_York';"+rollback);assert snap()==before
sql(rollback);assert snap()==before
sql(apply)
last=rows[-1]['expected_trail']['id']
sql(f"update trail_parking_i18n set notes='Owner edit' where lang='zh' and parking_id=(select id from trail_parking where trail_id={last});")
changed=snap();sql(apply,'Parking package records changed');sql(rollback,'Parking package records changed');assert snap()==changed
reset();sql(f"insert into trail_parking(trail_id,slug,active)values({last},'owner-inactive',false);");before=snap();sql(apply,'Reviewed practical baseline changed');assert snap()==before
reset();sql(f"update trail_access_i18n set directions='Owner later edit' where lang='en' and access_id=(select id from trail_access where trail_id={last});");before=snap();sql(apply,'Reviewed practical baseline changed');assert snap()==before
reset();sql(f"update trails set start_point_name='Different start' where id={last};");before=snap();sql(apply,'Reviewed route identity changed');assert snap()==before
reset();sql('alter table trail_parking disable row level security;');before=snap();sql(apply,'Required practical table with RLS missing');assert snap()==before
reset();sql(apply);sql(f'create table bookmarks(parking_id bigint references trail_parking on delete cascade);insert into bookmarks select id from trail_parking where trail_id={last};');before=snap();sql(rollback,'Parking referenced');assert snap()==before;assert sql('select count(*) from bookmarks;')=='1'
reset();sql(f"create function mutate_card() returns trigger language plpgsql as $$begin if new.trail_id={last} then update trail_access set address='Unrequested' where trail_id=new.trail_id;end if;return new;end$$;create trigger mutate_card after insert on trail_parking for each row execute function mutate_card();");before=snap();sql(apply,'Unexpected practical side effect');assert snap()==before
print('PASS: 16 parking/64 texts; all 28 access/112 texts and 9 original parking/36 texts unchanged; preserved receipts/routes/user links; identity and inactive conflicts atomic; RLS; timezone-safe idempotency/rollback/reapply; later-edit and CASCADE protection')
